return UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.MeshFilter>(true)).Where(f=>f.GetComponent<UnityEngine.Renderer>()!=null&&f.GetComponentInParent<OVRCameraRig>(true)==null&&f.sharedMesh!=null&&!f.name.StartsWith("Grass")).Select(f=>new{name=f.name,model=UnityEditor.AssetDatabase.GetAssetPath(f.sharedMesh),materials=f.GetComponent<UnityEngine.Renderer>().sharedMaterials.Where(m=>m!=null).Select(m=>m.shader.name).Distinct().ToArray()}).GroupBy(x=>x.model).Select(g=>new{model=g.Key,names=g.Select(x=>x.name).Distinct().ToArray(),shaders=g.SelectMany(x=>x.materials).Distinct().ToArray()}).ToArray();
